import ast, sys
for fname in ("notification_server.py", "transport.py"):
    tree = ast.parse(open(fname).read(), fname)
    imported = set()
    for node in ast.walk(tree):
        if isinstance(node, ast.ImportFrom):
            for alias in node.names:
                imported.add(alias.asname or alias.name)
        elif isinstance(node, ast.Import):
            for alias in node.names:
                imported.add((alias.asname or alias.name).split(".")[0])
    src = open(fname).read()
    for name in sorted(imported):
        # crude usage check: appears more than once (import line + usage)
        count = src.count(name)
        if count <= 1:
            print(f"{fname}: possibly unused import {name!r}")
EOF
